"المزوّد مطفأ — يعمل «المخطّط المدمج» فقط.":"प्रोवाइडर बंद है — सिर्फ़ «बिल्ट-इन प्लानर» चलता है।",
"متصل بـ {0} · {1} — الخطة والكود من النموذج، مع فحص حقيقي للأصول والـAPI قبل التطبيق.":"{0} · {1} से जुड़ा — प्लान और कोड मॉडल से, लागू करने से पहले एसेट और API की असली जाँच के साथ।",
"الذكاء المجاني متاح لمن سجّل الدخول بحساب Google — سجّل الدخول وسيعمل وحده. حتى ذلك الحين يعمل «المخطّط المدمج».":"फ़्री AI Google से साइन इन करने वालों के लिए है — साइन इन करें और यह खुद चलेगा। तब तक «बिल्ट-इन प्लानर» चलता है।",
"لا يوجد مزوّد AI: يعمل «المخطّط المدمج» — يتعرّف على كلمات مفتاحية ويبني أنظمة جاهزة حقيقية. هذا ليس ذكاءً اصطناعيًا؛ لطلبات حرّة صِلْ مزوّدًا من ⚙.":"कोई AI प्रोवाइडर नहीं: «बिल्ट-इन प्लानर» चलता है — यह कीवर्ड पहचानकर असली तैयार सिस्टम बनाता है। यह AI नहीं है; खुले अनुरोधों के लिए ⚙ से कोई प्रोवाइडर जोड़ें।",
"قل لي ما نوع اللعبة التي تريدها وسأخطّط لها وأبنيها وأختبرها. تستطيع إيقافي في أي لحظة، ولكل تغيير نقطة رجوع.":"बताइए आपको कैसा गेम चाहिए, मैं उसका प्लान बनाकर उसे बनाऊँगा और टेस्ट करूँगा। आप मुझे कभी भी रोक सकते हैं, और हर बदलाव का रीस्टोर पॉइंट है।",
"اطلب ما تريد. سأقرأ مشروعك أولًا، ثم أضع خطة، ثم أنفّذ وأبني وأختبر وأصلح.":"जो चाहिए माँगिए। मैं पहले आपका प्रोजेक्ट पढ़ूँगा, फिर प्लान बनाऊँगा, फिर लागू करूँगा, बिल्ड, टेस्ट और ठीक करूँगा।",
"⚙ ربط نموذج ذكاء اصطناعي":"⚙ AI मॉडल जोड़ें",
