"هذه هي الملفات التي يستطيع المساعد استعمالها في هذا المشروع. يرى بياناتها فقط (الاسم والنوع والأبعاد) — ويُحمَّل الملف نفسه عندما يضعه في المشهد. ملفات Google Drive الأخرى وملفات الآخرين الخاصة لا يراها أبدًا.":"ये वे फ़ाइलें हैं जिन्हें असिस्टेंट इस प्रोजेक्ट में इस्तेमाल कर सकता है। यह सिर्फ़ उनका डेटा (नाम, टाइप और साइज़) देखता है — फ़ाइल खुद तब लोड होती है जब वह उसे सीन में रखता है। आपकी दूसरी Google Drive फ़ाइलें या दूसरों की निजी फ़ाइलें यह कभी नहीं देखता।",
