"بث حقيقي من جهازك مباشرة إلى كل مشاهد (WebRTC). حدوده الحقيقية: عدد قليل من المشاهدين (كل مشاهد اتصال منفصل من جهازك)، وبعض الشبكات تحتاج خادم TURN{0} للبث الواسع يلزم مزوّد بث (SFU/CDN).":"आपके डिवाइस से सीधे हर दर्शक तक असली स्ट्रीम (WebRTC)। असली सीमाएँ: कम दर्शक (हर दर्शक आपके डिवाइस से अलग कनेक्शन है), और कुछ नेटवर्क को TURN सर्वर चाहिए{0} बड़े पैमाने पर स्ट्रीम के लिए स्ट्रीमिंग प्रोवाइडर (SFU/CDN) चाहिए।",
