"{0}الخطة المجانية تسمح بعدد محدود من الرموز في الدقيقة. جرّب نموذجًا حدّه أكبر (مثل llama-3.3-70b-versatile في Groq)، أو ابدأ محادثة جديدة، أو انتظر دقيقة.":"{0}फ़्री प्लान में प्रति मिनट सीमित टोकन मिलते हैं। बड़ी सीमा वाला मॉडल आज़माएँ (जैसे Groq पर llama-3.3-70b-versatile), नई चैट शुरू करें, या एक मिनट रुकें।",
