"NEXUS AI — مجاني":"NEXUS AI — फ़्री",
"ذكاء اصطناعي مجاني يقدّمه صاحب المنصة لكل من سجّل الدخول بحساب Google. اختر النموذج فقط — المفاتيح على خادم الموقع ولا تظهر لأحد. إذا انتهى حدّ مفتاح ينتقل وحده إلى التالي، ثم إلى النموذج الآخر.":"प्लेटफ़ॉर्म के मालिक की तरफ़ से Google से साइन इन करने वाले हर व्यक्ति के लिए फ़्री AI। बस मॉडल चुनें — कीज़ साइट के सर्वर पर हैं और कोई उन्हें नहीं देखता। किसी की की सीमा खत्म होने पर यह खुद अगली पर जाता है, फिर दूसरे मॉडल पर।",
"سريع جدًا. المفتاح مجاني من لوحة Groq ويبدأ بـ gsk_.":"बहुत तेज़। की Groq कंसोल से फ़्री मिलती है और gsk_ से शुरू होती है।",
"نماذج Grok من xAI. المفتاح يبدأ بـ xai-.":"xAI के Grok मॉडल। की xai- से शुरू होती है।",
"يحتاج ترويسة الوصول المباشر من المتصفح؛ وهي مضافة تلقائيًا.":"डायरेक्ट ब्राउज़र एक्सेस हेडर चाहिए; यह अपने आप जुड़ता है।",
"المفتاح من Google AI Studio (يبدأ بـ AIza أو AQ.).":"Google AI Studio की की (AIza या AQ. से शुरू होती है)।",
"نموذج محلي (Ollama / LM Studio)":"लोकल मॉडल (Ollama / LM Studio)",
"يعمل بلا إنترنت إذا كان الخادم يعمل على جهازك ويسمح بـCORS.":"बिना इंटरनेट चलता है अगर सर्वर आपके डिवाइस पर चलता हो और CORS की अनुमति दे।",
"أي موقع (Base URL)":"कोई भी साइट (Base URL)",
"أي موقع متوافق مع OpenAI (مثل cleanapis): الصق رابطه الذي ينتهي بـ /v1 ثم مفتاحه — تظهر نماذجه لتختار منها، ويُختبر بطلب حقيقي قبل الاستعمال.":"कोई भी OpenAI-संगत साइट (जैसे cleanapis): /v1 पर खत्म होने वाला उसका पता पेस्ट करें, फिर उसकी की — उसके मॉडल चुनने के लिए दिखते हैं, और इस्तेमाल से पहले असली अनुरोध से टेस्ट होता है।",
"لم يُحفظ الإعداد: هذا المتصفح لا يسمح بالحفظ (وضع التصفّح الخاص أو ذاكرة ممتلئة). افتح الموقع في متصفح عادي مثل Chrome.":"सेटिंग सेव नहीं हुई: यह ब्राउज़र सेव करने नहीं देता (प्राइवेट ब्राउज़िंग या भरी स्टोरेज)। साइट को Chrome जैसे सामान्य ब्राउज़र में खोलें।",
"دالة الذكاء تعمل على خادم الموقع لكن بلا مفاتيح. صاحب الموقع يضع GEMINI_KEYS و GROQ_KEYS في Netlify ← Site configuration ← Environment variables، ثم Deploys ← Trigger deploy.":"AI फ़ंक्शन साइट के सर्वर पर चलता है, पर बिना कीज़ के। साइट मालिक Netlify ← Site configuration ← Environment variables में GEMINI_KEYS और GROQ_KEYS डालें, फिर Deploys ← Trigger deploy।",
"خادم الموقع لا يشغّل دالة الذكاء (netlify/edge-functions/ai.js) — غالبًا لأن الموقع رُفع بالسحب والإفلات، والدوال لا تعمل هكذا. صاحب الموقع يربطه بـ GitHub في Netlify (Base directory = nexus) ثم يضع المفاتيح في Environment variables.":"साइट का सर्वर AI फ़ंक्शन (netlify/edge-functions/ai.js) नहीं चलाता — शायद इसलिए कि साइट ड्रैग-एंड-ड्रॉप से अपलोड हुई, और फ़ंक्शन ऐसे नहीं चलते। साइट मालिक इसे Netlify में GitHub से जोड़ें (Base directory = nexus), फिर Environment variables में कीज़ डालें।",
"تعذّر الوصول إلى الخادم (Network / CORS)":"सर्वर तक नहीं पहुँच सके (Network / CORS)",
