"المساعد يقرأ ملفاتك وكائناتك وأصولك — ويرسل ما يخصّ سؤالك فقط. أوامر المشهد تُنفَّذ فعليًا: «أضف سيارة بجانب المبنى»، «اجعلها أكبر»، «حلل لعبتي»، «تراجع».":"असिस्टेंट आपकी फ़ाइलें, ऑब्जेक्ट और एसेट पढ़ता है — और सिर्फ़ वही भेजता है जो आपके सवाल के लिए ज़रूरी हो। सीन कमांड सच में चलती हैं: «इमारत के पास एक कार जोड़ो», «इसे बड़ा करो», «मेरे गेम का विश्लेषण करो», «अनडू»।",
"بلا مزوّد تعمل أوامر المشهد والأصول فعليًا: «أضف سيارة بجانب المبنى»، «اجعلها أكبر»، «ضعها خلف المنزل»، «حلل لعبتي»، «تراجع». أما المحادثة الحرّة وتعديل الكود بطلب حر فتحتاج نموذجًا.":"बिना प्रोवाइडर के सीन और एसेट कमांड सच में चलती हैं: «इमारत के पास एक कार जोड़ो», «इसे बड़ा करो», «इसे घर के पीछे रखो», «मेरे गेम का विश्लेषण करो», «अनडू»। खुली चैट और खुले अनुरोध पर कोड बदलने के लिए मॉडल चाहिए।",
