"اقتراح المساعد — راجعه وعدّله قبل الاعتماد. الذكاء الاصطناعي قد يخطئ.":"असिस्टेंट का सुझाव — स्वीकार करने से पहले देखें और बदलें। AI गलती कर सकता है।",
