"هذا المتصفح لا يدعم الصوت المباشر (WebRTC / الميكروفون)":"यह ब्राउज़र लाइव आवाज़ (WebRTC / माइक्रोफ़ोन) का समर्थन नहीं करता",
"الصوت يعمل بين أعضاء فريق المشروع — لا يوجد فريق متصل هنا":"आवाज़ प्रोजेक्ट की टीम के सदस्यों के बीच चलती है — यहाँ कोई टीम जुड़ी नहीं",
"🎤 الميكروفون مرفوض":"🎤 माइक्रोफ़ोन से इनकार हुआ",
"المتصفح يمنع NEXUS من الميكروفون. افتح إعدادات الموقع (رمز القفل بجانب العنوان) واسمح بالميكروفون ثم أعد المحاولة.":"ब्राउज़र NEXUS को माइक्रोफ़ोन से रोकता है। साइट की सेटिंग्स खोलें (पते के पास ताले का निशान), माइक्रोफ़ोन की अनुमति दें, फिर कोशिश करें।",
"🎤 الصوت مع الفريق":"🎤 टीम के साथ आवाज़",
"سيطلب المتصفح الآن إذن استخدام الميكروفون. الصوت يذهب مباشرة بين أعضاء الفريق (WebRTC) ولا يُسجَّل ولا يُحفظ في أي مكان. يمكنك الكتم أو الإيقاف في أي وقت.":"ब्राउज़र अब माइक्रोफ़ोन इस्तेमाल की अनुमति माँगेगा। आवाज़ सीधे टीम के सदस्यों के बीच जाती है (WebRTC) और कहीं रिकॉर्ड या सेव नहीं होती। आप कभी भी म्यूट या बंद कर सकते हैं।",
"🔇 كتمك مالك المشروع — لن يسمعك الفريق حتى يلغي الكتم":"🔇 प्रोजेक्ट के मालिक ने आपको म्यूट किया — अनम्यूट होने तक टीम आपको नहीं सुनेगी",
"🎤 أُلغي كتمك — يمكنك التحدث":"🎤 आप अनम्यूट हुए — अब बोल सकते हैं",
"كتمك المالك — لا يمكنك إلغاء الكتم الآن":"मालिक ने आपको म्यूट किया — आप अभी अनम्यूट नहीं कर सकते",
"تعذّر الاتصال المباشر ببعض الأعضاء — قد تمنعه شبكتكم":"कुछ सदस्यों से सीधे नहीं जुड़ सके — आपके नेटवर्क इसे रोक सकते हैं",
"🔈 اضغط لسماع الفريق":"🔈 टीम को सुनने के लिए टैप करें",
"🟢 متصل":"🟢 जुड़ा है",
"🟠 غير متصل — تُرسل تعديلاتك عند عودة الاتصال":"🟠 ऑफ़लाइन — कनेक्शन लौटने पर आपके बदलाव भेजे जाएँगे",
"هذا المشروع لك وحدك الآن. ادعُ أصدقاءك ليعملوا معك في نفس المشروع: كلٌّ بدوره، وترون بعضكم وتتكلمون بالصوت.":"यह प्रोजेक्ट अभी सिर्फ़ आपका है। अपने दोस्तों को उसी प्रोजेक्ट पर साथ काम करने बुलाएँ: हर कोई अपनी भूमिका में, एक-दूसरे को देखते और आवाज़ से बात करते हुए।",
"لا يوجد فريق في هذا المشروع.":"इस प्रोजेक्ट में कोई टीम नहीं।",
