"يصبح هو المالك: يدير الأعضاء والنشر والإعدادات. لا يمكنك استعادتها إلا إذا أعادها لك. اللعبة المنشورة سابقًا تبقى باسم من نشرها.":"वे मालिक बन जाते हैं: सदस्य, पब्लिशिंग और सेटिंग्स संभालते हैं। जब तक वे न लौटाएँ आप इसे वापस नहीं पा सकते। पहले पब्लिश हुए गेम पब्लिश करने वाले के नाम पर रहते हैं।",
