"تعمل في صندوق معزول: لا إنترنت، لا وصول إلى حسابك أو بياناتك أو مفاتيح AI أو ملفات الموقع.":"यह एक अलग बॉक्स में चलता है: न इंटरनेट, न आपके अकाउंट, डेटा, AI कीज़ या साइट की फ़ाइलों तक पहुँच।",
