"الإضافات أدوات صغيرة للاستوديو. كل إضافة تعمل في صندوق معزول بلا إنترنت، ولا تصل إلى حسابك أو بياناتك أو مفاتيح AI أو ملفات الموقع — فقط ما تسمح به صلاحياتها، وضمن حدود دورك في المشروع.":"प्लगइन स्टूडियो के छोटे टूल हैं। हर प्लगइन बिना इंटरनेट के अलग बॉक्स में चलता है, और आपके अकाउंट, डेटा, AI कीज़ या साइट की फ़ाइलों तक नहीं पहुँचता — सिर्फ़ वही जो उसकी अनुमतियाँ दें, प्रोजेक्ट में आपकी भूमिका के दायरे में।",
