"إن كان مفتاح إعداد Firebase للويب فهو عام بطبيعته — قيّده بنطاق موقعك من Google Cloud Console. إن كان مفتاح Gemini أو Maps فهو سرّ: احذفه من هنا وضعه في متغيرات بيئة Netlify (Function / Edge Function).":"अगर यह Firebase वेब सेटअप की है तो स्वभाव से सार्वजनिक है — Google Cloud Console से इसे अपनी साइट के डोमेन तक सीमित करें। अगर यह Gemini या Maps की है तो राज़ है: इसे यहाँ से हटाकर Netlify के environment variables (Function / Edge Function) में रखें।",
"احذفه من المشروع فورًا وأبطله (Revoke) من لوحة المزوّد وأنشئ مفتاحًا جديدًا. الأسرار مكانها متغيرات بيئة Netlify على الخادم فقط — أي كود في اللعبة يراه كل لاعب.":"इसे प्रोजेक्ट से तुरंत हटाएँ, प्रोवाइडर के डैशबोर्ड से Revoke करें और नई की बनाएँ। राज़ सिर्फ़ सर्वर पर Netlify के environment variables में रहते हैं — गेम का कोई भी कोड हर खिलाड़ी देखता है।",
"لا تكتب كلمات السر أو الرموز في كود اللعبة — كل لاعب يستطيع قراءتها. انقلها إلى الخادم (Netlify Function) واطلب النتيجة فقط.":"गेम के कोड में पासवर्ड या टोकन न लिखें — हर खिलाड़ी उन्हें पढ़ सकता है। उन्हें सर्वर (Netlify Function) पर ले जाएँ और सिर्फ़ नतीजा माँगें।",
"كتابة HTML مباشرة (innerHTML)":"सीधे HTML लिखना (innerHTML)",
"استعمل عناصر DOM أو UI.* بنص عادي.":"सादे टेक्स्ट के साथ DOM एलिमेंट या UI.* इस्तेमाल करें।",
"احذفه — استعمل UI.* لعرض النصوص.":"इसे हटाएँ — टेक्स्ट दिखाने के लिए UI.* इस्तेमाल करें।",
"لا تنفّذ نصوصًا ككود — خصوصًا ما يأتي من الشبكة أو من لاعب آخر.":"टेक्स्ट को कोड की तरह न चलाएँ — खासकर नेटवर्क या किसी दूसरे खिलाड़ी से आया टेक्स्ट।",
"لا تبنِ كودًا من نصوص.":"टेक्स्ट से कोड न बनाएँ।",
"setTimeout/setInterval بنص":"स्ट्रिंग के साथ setTimeout/setInterval",
"مرّر دالة وليس نصًا.":"स्ट्रिंग नहीं, फ़ंक्शन दें।",
"حلقة لا تنتهي (while(true) بدون break)":"कभी न खत्म होने वाला लूप (break के बिना while(true))",
"قد تجمّد اللعبة على الهاتف — أضف شرط خروج أو استعمل update(dt).":"यह फ़ोन पर गेम जाम कर सकता है — बाहर निकलने की शर्त जोड़ें या update(dt) इस्तेमाल करें।",
"إرسال شبكي في كل إطار":"हर फ़्रेम में नेटवर्क पर भेजना",
"update() تعمل ~60 مرة في الثانية — أرسل كل 100–250ms فقط (تكلفة Firebase وتأخير).":"update() प्रति सेकंड ~60 बार चलता है — सिर्फ़ हर 100–250ms पर भेजें (Firebase की लागत और देरी)।",
"مؤقت سريع جدًا":"बहुत तेज़ टाइमर",
"فترات أقل من 20ms تستهلك البطارية — استعمل update(dt).":"20ms से कम अंतराल बैटरी खाते हैं — update(dt) इस्तेमाल करें।",
"قسّمه إلى ملفات أصغر — أسهل للمراجعة وللدمج بين أعضاء الفريق.":"इसे छोटी फ़ाइलों में बाँटें — रिव्यू और टीम के सदस्यों के बीच मर्ज करना आसान।",
"وسم script داخل واجهة HTML":"HTML इंटरफ़ेस के अंदर script टैग",
"المحرك يحذفه عند البناء — ضع المنطق في ملفات JS.":"बिल्ड करते समय इंजन इसे हटा देता है — लॉजिक JS फ़ाइलों में रखें।",
