"قد يُستعمل لتنفيذ صفحة ضارة — احذفه.":"इससे कोई हानिकारक पेज चलाया जा सकता है — इसे हटाएँ।",
"رابط غير مشفّر (http)":"बिना एन्क्रिप्शन का लिंक (http)",
"رابط إلى عنوان IP مباشر":"सीधे IP पते का लिंक",
"تأكّد من مصدره — الروابط الموثوقة تستعمل اسم نطاق.":"इसका स्रोत जाँचें — भरोसेमंद लिंक डोमेन नाम इस्तेमाल करते हैं।",
"رابط مختصر":"छोटा लिंक",
"الروابط المختصرة تخفي وجهتها — استعمل الرابط الكامل.":"छोटे लिंक अपनी मंज़िल छिपाते हैं — पूरा लिंक इस्तेमाल करें।",
"رابط لتنزيل برنامج":"प्रोग्राम डाउनलोड करने का लिंक",
"لا توجّه اللاعبين لتنزيل برامج.":"खिलाड़ियों को प्रोग्राम डाउनलोड करने न भेजें।",
"{0} أعضاء يملكون صلاحية تعديل (مطوّر/باني)":"{0} सदस्यों के पास एडिट की अनुमति है (डेवलपर/बिल्डर)",
"أعطِ كل عضو أقل دور يحتاجه: من يختبر فقط يكفيه Tester، ومن يتابع يكفيه Viewer.":"हर सदस्य को उतनी ही भूमिका दें जितनी चाहिए: जो सिर्फ़ टेस्ट करता है उसके लिए Tester काफ़ी है, जो सिर्फ़ देखता है उसके लिए Viewer।",
"لا أعضاء":"कोई सदस्य नहीं",
"الإضافات":"प्लगइन",
"اترك صلاحية الكتابة فقط للإضافات التي تثق بها، وعطّل ما لا تستعمله.":"लिखने की अनुमति सिर्फ़ भरोसेमंद प्लगइन को दें, और जो इस्तेमाल नहीं करते उसे बंद करें।",
"ألغِ الدعوات القديمة من «إدارة الفريق».":"पुराने न्योते «टीम प्रबंधित करें» से रद्द करें।",
"حدود لوحة الصدارة واسعة جدًا":"लीडरबोर्ड की सीमाएँ बहुत खुली हैं",
"لوحة الصدارة":"लीडरबोर्ड",
"الخادم يرفض النتائج المستحيلة حسب هذه الحدود — كلما كانت أدق (أقصى نتيجة ونقاط/ثانية حقيقية) صعُب التلاعب.":"सर्वर इन सीमाओं से असंभव स्कोर ठुकराता है — जितनी सटीक (असली सबसे ऊँचा स्कोर और पॉइंट/सेकंड), धोखा उतना मुश्किल।",
"الموقع يعمل بدون HTTPS":"साइट बिना HTTPS के चलती है",
"انشر NEXUS على https (Netlify يوفّره تلقائيًا).":"NEXUS को https पर पब्लिश करें (Netlify यह अपने आप देता है)।",
"أكمل إعداد Firebase في أعلى index.html.":"index.html के ऊपर Firebase सेटअप पूरा करें।",
"هذا الجهاز":"यह डिवाइस",
"مفاتيحك محفوظة على جهازك فقط ولا تُرفع. ألعاب الآخرين والفريق تعمل في صندوق معزول لا يصل إليها. احذفها من «مزوّدي الذكاء الاصطناعي» إن كان الجهاز مشتركًا.":"आपकी कीज़ सिर्फ़ आपके डिवाइस पर सेव हैं और कभी अपलोड नहीं होतीं। दूसरों के और टीम के गेम एक अलग बॉक्स में चलते हैं जो उन तक नहीं पहुँचता। डिवाइस साझा हो तो उन्हें «AI प्रोवाइडर» से हटाएँ।",
"Firestore Rules (المنشورة فعلًا)":"Firestore Rules (असल में पब्लिश)",
"انشر firestore.rules من المستودع: firebase deploy --only firestore:rules — القواعد الحالية تبدو «وضع الاختبار» وتكشف مشاريع الناس وتقاريرهم.":"रिपॉज़िटरी से firestore.rules डिप्लॉय करें: firebase deploy --only firestore:rules — मौजूदा नियम «टेस्ट मोड» जैसे लगते हैं और लोगों के प्रोजेक्ट और रिपोर्ट खोलते हैं।",
