"الصندوق مسجّل باسم {0}. تستطيع استعمال الذكاء المجاني، أو إضافة مفتاحك الخاص من «مزوّدو الذكاء الاصطناعي».":"बॉक्स {0} के नाम पर रजिस्टर है। आप मुफ़्त AI इस्तेमाल कर सकते हैं, या «AI प्रदाता» से अपनी की जोड़ सकते हैं।",
"لا صاحب للصندوق بعد: أول حساب يحفظ مفتاحًا يصبح صاحبه — هذا أنت ({0}). بعدها لا يستطيع غيرك إضافة المفاتيح أو حذفها.":"बॉक्स का अभी कोई मालिक नहीं: जो पहला अकाउंट की सेव करेगा वही इसका मालिक बनेगा — यानी आप ({0})। उसके बाद कोई और कीज़ जोड़ या हटा नहीं सकता।",
