"ضع هنا مفاتيح Gemini (Google AI Studio) أو Groq أو OpenRouter أو Claude (Anthropic — مدفوع، ولا يستعمله «auto» إلا إذا اختار اللاعب نموذج Claude أو ANTHROPIC_AUTO=1) مرة واحدة. تُحفظ على خادم الموقع فقط: لا يراها أحد، ولا تُرسل إلى أي صفحة — ولا حتى إليك بعد الحفظ (يظهر آخر 4 أحرف فقط). كل من ليس لديه مفتاح يحصل على الذكاء المجاني ويختار النموذج فقط. إذا انتهى حدّ مفتاح يُستعمل التالي تلقائيًا، ثم Groq، ثم «غير متاح الآن».":"यहाँ एक बार Gemini (Google AI Studio), Groq, OpenRouter या Claude की कीज़ डालें (Anthropic — पेड; «auto» इसे तभी इस्तेमाल करता है जब खिलाड़ी Claude मॉडल चुने या ANTHROPIC_AUTO=1 हो)। ये सिर्फ़ साइट के सर्वर पर सेव होती हैं: इन्हें कोई नहीं देखता, और ये किसी पेज पर नहीं भेजी जातीं — सेव करने के बाद आपको भी नहीं (सिर्फ़ आख़िरी 4 अक्षर दिखते हैं)। जिसके पास की नहीं है उसे मुफ़्त AI मिलता है और वह सिर्फ़ मॉडल चुनता है। अगर किसी की की सीमा ख़त्म हो जाए तो अगली अपने-आप इस्तेमाल होती है, फिर Groq, फिर «अभी उपलब्ध नहीं»।",
"أو: مفتاح لي أنا فقط (في هذا المتصفح)":"या: सिर्फ़ मेरे लिए की (इस ब्राउज़र में)",
