"جهّز نصًّا جاهزًا للصقه في Netlify":"Netlify में पेस्ट करने के लिए तैयार टेक्स्ट बनाएँ",
"أضف مفاتيحك":"अपनी कीज़ जोड़ें",
"إلى أن يعمل الصندوق: الصق مفاتيحك هنا، وسأجهّز لك نصًّا واحدًا تلصقه في Netlify — يعمل فورًا بعد Trigger deploy، ولا يرى أحد المفاتيح. النص يُصنع على جهازك ولا يُرسل إلى أي مكان.":"जब तक बॉक्स काम नहीं करता: अपनी कीज़ यहाँ पेस्ट करें, और मैं आपके लिए एक टेक्स्ट बनाऊँगा जिसे आप Netlify में पेस्ट करें — यह Trigger deploy के तुरंत बाद काम करता है, और कोई कीज़ नहीं देखता। टेक्स्ट आपके डिवाइस पर बनता है और कहीं नहीं भेजा जाता।",
"أضف مفاتيح":"कीज़ जोड़ें",
"لا مفاتيح في الصندوق بعد.":"बॉक्स में अभी कोई की नहीं।",
"لن يُستعمل بعد الآن للذكاء المجاني.":"अब इसे मुफ़्त AI के लिए इस्तेमाल नहीं किया जाएगा।",
"مهم: Deploys ← Trigger deploy ← Deploy site — أي متغيّر جديد لا يصل إلى الخادم إلا بعد نشر جديد":"ज़रूरी: Deploys → Trigger deploy → Deploy site — कोई भी नया वेरिएबल नए डिप्लॉय के बाद ही सर्वर तक पहुँचता है",
"FIREBASE_SERVICE_ACCOUNT موجود لكنه ليس محتوى ملف JSON":"FIREBASE_SERVICE_ACCOUNT मौजूद है लेकिन यह JSON फ़ाइल का कंटेंट नहीं है",
"افتح ملف JSON الذي نزّلته من Firebase بمحرّر نصوص (أو «فتح كنص» في تطبيق الملفات)":"Firebase से डाउनलोड की गई JSON फ़ाइल को किसी टेक्स्ट एडिटर में खोलें (या फ़ाइल ऐप में «टेक्स्ट के रूप में खोलें»)",
"انسخ كل ما فيه — من { إلى } — والصقه قيمةً لـ FIREBASE_SERVICE_ACCOUNT":"इसमें जो कुछ है — { से } तक — कॉपी करें और FIREBASE_SERVICE_ACCOUNT की वैल्यू के रूप में पेस्ट करें",
"محتوى FIREBASE_SERVICE_ACCOUNT ناقص":"FIREBASE_SERVICE_ACCOUNT का कंटेंट अधूरा है",
