"Google رفض حساب الخدمة":"Google ने सर्विस अकाउंट ठुकरा दिया",
"ضع محتوى الملف الجديد بدل القديم في FIREBASE_SERVICE_ACCOUNT":"FIREBASE_SERVICE_ACCOUNT में पुरानी की जगह नई फ़ाइल का कंटेंट डालें",
"حساب الخدمة يعمل، لكن Firestore رفض":"सर्विस अकाउंट काम करता है, लेकिन Firestore ने मना किया",
"تأكد أن ملف JSON من نفس مشروع Firebase الذي يستعمله الموقع":"पक्का करें कि JSON फ़ाइल उसी Firebase प्रोजेक्ट की है जिसे साइट इस्तेमाल करती है",
"وأن Firestore Database مفعّل فيه (Firebase Console ← Firestore Database ← Create database)":"और उसमें Firestore Database चालू है (Firebase Console → Firestore Database → Create database)",
"مخزن Netlify رفض الحفظ":"Netlify स्टोर ने सेव करने से मना किया",
"Deploys ← Trigger deploy ← Deploy site، ثم أعد فتح هذا الصندوق":"Deploys → Trigger deploy → Deploy site, फिर यह बॉक्स दोबारा खोलें",
"إن بقي: ضع FIREBASE_SERVICE_ACCOUNT كطريق بديل (الخطوات تظهر هنا بعد إزالة المشكلة)":"अगर फिर भी रहे: FIREBASE_SERVICE_ACCOUNT को वैकल्पिक रास्ते के रूप में सेट करें (समस्या हटने के बाद क़दम यहाँ दिखेंगे)",
"لا يوجد بعد مكان على الخادم يحفظ المفاتيح":"सर्वर पर कीज़ सेव करने की अभी कोई जगह नहीं है",
"على موقع Netlify مربوط بـ GitHub يعمل الصندوق وحده (مخزن Netlify Blobs) — بعد أن تُنشر هذه النسخة الجديدة من NEXUS: Deploys ← Trigger deploy ← Deploy site. إن بقيت هذه الرسالة بعد النشر، فالطريق البديل مرة واحدة:":"GitHub से जुड़ी Netlify साइट पर बॉक्स अपने-आप काम करता है (Netlify Blobs स्टोर) — NEXUS का यह नया वर्ज़न डिप्लॉय होने के बाद: Deploys → Trigger deploy → Deploy site। अगर डिप्लॉय के बाद भी यह संदेश रहे, तो एक बार का वैकल्पिक रास्ता:",
"Firebase Console ← ⚙ Project settings ← Service accounts ← Generate new private key (يُنزَّل ملف JSON)":"Firebase Console → ⚙ Project settings → Service accounts → Generate new private key (एक JSON फ़ाइल डाउनलोड होगी)",
