"محتوى جنسي أو عُري":"यौन सामग्री या नग्नता",
"الفئة العمرية · Age rating":"आयु वर्ग · Age rating",
"لمن تناسب هذه اللعبة؟ تظهر على صفحتها وبطاقتها. فوق 3+ يحتاج اللاعب حسابًا يُعرف منه عمره.":"यह गेम किसके लिए सही है? यह इसके पेज और कार्ड पर दिखता है। 3+ से ऊपर खिलाड़ी को ऐसा अकाउंट चाहिए जिससे उसकी उम्र पता चले।",
"انتهى الوقت":"समय ख़त्म",
"🤖 الذكاء + فحص المحتوى:":"🤖 AI + कंटेंट जाँच:",
"🔍 فحص المحتوى:":"🔍 कंटेंट जाँच:",
"لم يُعثر على عنف أو رعب أو قمار أو محتوى للكبار في النصوص والأسماء.":"टेक्स्ट और नामों में कोई हिंसा, हॉरर, जुआ या वयस्क सामग्री नहीं मिली।",
"قرأ الأسماء والوصف ونصوص الكود — لا يرى الصور ولا يلعب اللعبة.":"इसने नाम, विवरण और कोड के टेक्स्ट पढ़े — यह इमेज नहीं देखता और गेम नहीं खेलता।",
