"السنة":"साल",
"🎂 كم عمرك؟":"🎂 आपकी उम्र कितनी है?",
"ليس الآن":"अभी नहीं",
"اختر الشهر والسنة":"महीना और साल चुनें",
"تاريخ في المستقبل":"भविष्य की तारीख़",
"تاريخ ميلادك محفوظ في حسابك من قبل":"आपकी जन्मतिथि पहले से आपके अकाउंट में सेव है",
"حساب جديد 🎉 — شهر وسنة ميلادك (اختياري الآن): يُحفظان في حسابك لا في هذا الجهاز، ويُحسب عمرك منهما تلقائيًا كل سنة. الألعاب فوق 3+ تحتاجهما.":"नया अकाउंट 🎉 — आपके जन्म का महीना और साल (अभी वैकल्पिक): ये आपके अकाउंट में सेव होते हैं, इस डिवाइस पर नहीं, और हर साल आपकी उम्र इनसे अपने-आप गिनी जाती है। 3+ से ऊपर के गेम्स को इनकी ज़रूरत होती है।",
"الألعاب والمواقع فوق 3+ تحتاج حسابًا يُعرف منه عمرك. سجّل الدخول (Google أو البريد) ثم أدخل شهر وسنة ميلادك مرة واحدة.":"3+ से ऊपर के गेम्स और साइटों के लिए ऐसा अकाउंट चाहिए जिससे आपकी उम्र पता चले। साइन इन करें (Google या ईमेल), फिर एक बार अपने जन्म का महीना और साल डालें।",
"كل لعبة وموقع له فئة عمرية (3+ · 7+ · 12+ · 16+ · 18+) يحدّدها فحص المحتوى والذكاء عند النشر. 3+ للجميع؛ ما فوقها يحتاج حسابًا فيه شهر وسنة ميلادك، ويتحقّق الخادم منها قبل أن يرسل اللعبة.":"हर गेम और साइट का एक आयु वर्ग (3+ · 7+ · 12+ · 16+ · 18+) होता है जिसे प्रकाशन के समय कंटेंट जाँच और AI तय करते हैं। 3+ सबके लिए है; उससे ऊपर के लिए ऐसा अकाउंट चाहिए जिसमें आपके जन्म का महीना और साल हो, और सर्वर गेम भेजने से पहले इसकी जाँच करता है।",
"سجّل الدخول ليُعرف عمرك.":"साइन इन करें ताकि आपकी उम्र पता चले।",
"لا يُغيَّر من الموقع — إن كان خطأً راسل صاحب الموقع.":"इसे साइट से नहीं बदला जा सकता — अगर यह गलत है तो साइट के मालिक को संदेश भेजें।",
"لم تُدخل تاريخ ميلادك بعد — ستلعب 3+ فقط حتى تُدخله.":"आपने अभी अपनी जन्मतिथि नहीं डाली — जब तक नहीं डालेंगे, सिर्फ़ 3+ खेल पाएँगे।",
