"زيادة السرعة":"गति बढ़ाएँ",
"⚠ «{0}» يقود أكثر من كائن — تغيير {1} فيه يسرّعها كلها. لتسريع «{2}» وحدها: «اجعلها قابلة للقيادة» (VehicleController بإعدادات خاصة بها).":"⚠ «{0}» एक से ज़्यादा ऑब्जेक्ट चलाता है — इसमें {1} बदलने से सब तेज़ हो जाएँगे। सिर्फ़ «{2}» को तेज़ करने के लिए: «इसे चलाने लायक बनाओ» (अपनी अलग सेटिंग्स वाला VehicleController)।",
"لم أجد نظام سرعة يحرّك {0} (لا مكوّن ولا سكربت يغيّر موضعها أو سرعتها).":"मुझे {0} को चलाने वाला कोई स्पीड सिस्टम नहीं मिला (कोई कंपोनेंट या स्क्रिप्ट इसकी पोज़िशन या वेग नहीं बदलती)।",
"{0}: لا يوجد ما يحرّكها أصلًا، لذلك لا توجد سرعة أغيّرها. أضيف لها نظام قيادة (VehicleController) بسرعة قصوى {1}؟":"{0}: इसे कुछ भी नहीं चलाता, इसलिए बदलने को कोई गति नहीं है। क्या मैं इसमें अधिकतम गति {1} वाला ड्राइविंग सिस्टम (VehicleController) जोड़ूँ?",
"نعم، أضف نظام القيادة":"हाँ, ड्राइविंग सिस्टम जोड़ें",
"Rigidbody (أرض صلبة)":"Rigidbody (ठोस ज़मीन)",
"أزرار اللمس":"टच बटन",
"«{0}» فيها نظام قيادة (VehicleController) يعمل — لمس: {1} · سرعة قصوى {2}":"«{0}» में चालू ड्राइविंग सिस्टम (VehicleController) है — टच: {1} · अधिकतम गति {2}",
"قيادة قديمة (يحلّ محلها VehicleController)":"पुरानी ड्राइविंग (इसकी जगह VehicleController)",
"«{0}» يقودها سكربتك {1} — لم أضف نظامًا ثانيًا فوقه. قل «ما مشكلتها؟» إن كانت لا تتحرك.":"«{0}» को आपकी स्क्रिप्ट {1} चलाती है — मैंने उसके ऊपर दूसरा सिस्टम नहीं जोड़ा। अगर यह नहीं चलता तो कहें «इसमें क्या दिक्कत है?»।",
"+ لمس":"+ टच",
"Rigidbody (كان ثابتًا فلا يتحرك)":"Rigidbody (यह स्थिर था इसलिए नहीं हिलता था)",
"يقودها اللاعب":"खिलाड़ी इसे चलाता है",
"لا توجد مركبة في المشهد — أضف واحدة («أضف سيارة») أو حدّد الكائن الذي تريد قيادته.":"सीन में कोई वाहन नहीं — एक जोड़ें («कार जोड़ो») या वह ऑब्जेक्ट चुनें जिसे चलाना है।",
