"نظام وقود · Fuel system":"फ़्यूल सिस्टम · Fuel system",
"«{0}» فيها نظام وقود أصلًا (Fuel: السعة {1}).":"«{0}» में पहले से फ़्यूल सिस्टम है (Fuel: क्षमता {1})।",
"⚠ الوقود يُعدّ ويُطلق «FuelEmpty»، لكن سكربت القيادة الحالي لا يستمع له — لن تتوقف عند فراغه حتى يستمع له.":"⚠ फ़्यूल घटता है और «FuelEmpty» भेजता है, लेकिन मौजूदा ड्राइविंग स्क्रिप्ट इसे नहीं सुनती — जब तक नहीं सुनेगी, ख़ाली होने पर नहीं रुकेगी।",
"+ Fuel (خزان 100 · عدّاد على الشاشة)":"+ Fuel (टैंक 100 · स्क्रीन पर मीटर)",
"— غيّرت tag إلى fuel":"— tag को fuel में बदला",
"لا توجد محطة وقود في مشهدك: ضع أي كائن واجعل tag له «fuel» — الاقتراب منه يعيد التعبئة.":"आपके सीन में कोई फ़्यूल स्टेशन नहीं: कोई भी ऑब्जेक्ट रखें और उसका tag «fuel» करें — उसके पास जाने से टैंक भरता है।",
"تتبّع الطريق · Follow path":"रास्ता फ़ॉलो करें · Follow path",
"يسير على نقاط المسار الموجودة ({0}: {1}…) بترتيب أسمائها":"यह मौजूदा पाथ पॉइंट ({0}: {1}…) पर उनके नामों के क्रम में चलता है",
"المسار من الطريق «{0}»: {1} نقاط (ذهاب وإياب على طوله). عدّلها من إعدادات FollowPath (points).":"सड़क «{0}» से पाथ: {1} पॉइंट (इसकी लंबाई पर आना-जाना)। इन्हें FollowPath की सेटिंग्स (points) से बदलें।",
"لا يوجد طريق ولا نقاط مسار في المشهد — أضفت 4 نقاط (Waypoint 1…4) حولها. حرّكها في المحرّر لترسم المسار الذي تريده.":"सीन में कोई सड़क या पाथ पॉइंट नहीं — मैंने इसके आसपास 4 पॉइंट (Waypoint 1…4) जोड़े। मनचाहा रास्ता बनाने के लिए इन्हें एडिटर में खिसकाएँ।",
"+ FollowPath (سرعة 8)":"+ FollowPath (गति 8)",
"VehicleController (الآن تسير وحدها على المسار)":"VehicleController (अब यह ख़ुद रास्ते पर चलता है)",
"بلا تحكم (تسير وحدها)":"बिना कंट्रोल (ख़ुद चलता है)",
"لا يوجد عدو في المشهد — حدّد الكائن الذي تريده أن يطارد ثم أعد الطلب.":"सीन में कोई दुश्मन नहीं — जिस ऑब्जेक्ट से पीछा करवाना है उसे चुनें, फिर से अनुरोध करें।",
"مطاردة اللاعب · Chase player":"खिलाड़ी का पीछा · Chase player",
"⚠ لا يوجد لاعب في المشهد ولا في الكود (Player.create أو كائن tag = player) — العدو ينتظر حتى يظهر لاعب.":"⚠ सीन या कोड में कोई खिलाड़ी नहीं (Player.create या tag = player वाला ऑब्जेक्ट) — दुश्मन खिलाड़ी के आने तक इंतज़ार करता है।",
"يطارد ضمن 25 م، ويتوقف ملاصقًا له ويطلق الحدث «EnemyReachedTarget» كل ثانية (اربطه بنظام الصحة إن أردت ضررًا).":"यह 25 मी के दायरे में पीछा करता है, उसके ठीक पास रुकता है और हर सेकंड «EnemyReachedTarget» इवेंट भेजता है (अगर नुकसान चाहिए तो इसे हेल्थ सिस्टम से जोड़ें)।",
"لا يوجد باب في المشهد — حدّد الكائن الذي تريده أن يفتح ثم أعد الطلب.":"सीन में कोई दरवाज़ा नहीं — जिस ऑब्जेक्ट को खोलना है उसे चुनें, फिर से अनुरोध करें।",
"باب يفتح عند الاقتراب · Proximity door":"पास आने पर खुलने वाला दरवाज़ा · Proximity door",
"+ DoorProximity (يفتح ضمن 3 م)":"+ DoorProximity (3 मी के अंदर खुलता है)",
"Rigidbody (يمنع المرور وهو مغلق)":"Rigidbody (बंद होने पर रास्ता रोकता है)",
"يدور 90° حول محوره. إن كان محور المجسم في منتصفه فالأفضل «slide» (انزلاق جانبي): غيّر mode في إعدادات DoorProximity.":"यह अपनी धुरी पर 90° घूमता है। अगर मॉडल की धुरी बीच में है तो «slide» (बगल में खिसकना) बेहतर है: DoorProximity की सेटिंग्स में mode बदलें।",
"⚠ لا يوجد لاعب بعد (Player.create أو tag = player) — الباب ينتظر من يقترب.":"⚠ अभी कोई खिलाड़ी नहीं (Player.create या tag = player) — दरवाज़ा किसी के पास आने का इंतज़ार करता है।",
"إعادة الظهور عند الموت · Respawn":"मरने पर फिर से प्रकट होना · Respawn",
"نقطة البداية: «{0}» الموجودة في مشهدك عند {1} — حرّكها لتغييرها.":"शुरुआती पॉइंट: आपके सीन में «{0}» {1} पर — बदलने के लिए इसे खिसकाएँ।",
"+ نقطة البداية":"+ शुरुआती पॉइंट",
"في مركز العالم":"वर्ल्ड के केंद्र में",
"نظام جاهز: إعادة الظهور":"तैयार सिस्टम: फिर से प्रकट होना",
"⚠ في كودك الصحة تصل إلى الصفر لكن لا يُطلق حدث موت — أضف هناك: Events.emit(\"PlayerDied\")":"⚠ आपके कोड में हेल्थ शून्य तक पहुँचती है लेकिन मौत का इवेंट नहीं भेजा जाता — वहाँ जोड़ें: Events.emit(\"PlayerDied\")",
"اللاعب: Player.create أو أي كائن tag = player":"खिलाड़ी: Player.create या कोई भी tag = player वाला ऑब्जेक्ट",
"«الموت» = السقوط تحت y={0}، أو الأحداث: {1}. {2}":"«मौत» = y={0} से नीचे गिरना, या इवेंट: {1}। {2}",
"إيقاف كل السيارات عند نهاية السباق · Stop on race end":"रेस ख़त्म होने पर सभी कारें रोकें · Stop on race end",
