"في آخر الطريق":"सड़क के आख़िर में",
"نظام جاهز: نهاية السباق":"तैयार सिस्टम: रेस का अंत",
"عند النهاية: كل سيارة tag = vehicle يصير جسمها ثابتًا (تتوقف مهما كان السكربت الذي يقودها)، وVehicleController يكبح بنفسه.":"अंत में: tag = vehicle वाली हर कार की बॉडी स्थिर हो जाती है (उसे चलाने वाली स्क्रिप्ट कोई भी हो, वह रुक जाती है), और VehicleController ख़ुद ब्रेक लगाता है।",
"اللعب الجماعي · Multiplayer":"मल्टीप्लेयर · Multiplayer",
"اللعبة كلها":"पूरा गेम",
"مشروعك فيه نظام لعب جماعي كتبته: «{0}» (يستعمل Network.room). لن أضيف نظامًا ثانيًا فوقه — اطلب تعديله مباشرة، مثل «اجعل {1} يرسل الدوران أيضًا».":"आपके प्रोजेक्ट में आपका लिखा मल्टीप्लेयर सिस्टम है: «{0}» (Network.room इस्तेमाल करता है)। मैं इसके ऊपर दूसरा सिस्टम नहीं जोड़ूँगा — इसे सीधे बदलने को कहें, जैसे «{1} को रोटेशन भी भेजने दो»।",
"من يمثّل اللاعب في لعبتك؟ حدّد الكائن (سيارتك أو شخصيتك) ثم قل «أضف Multiplayer» — أو أضف لاعبًا بـ Player.create.":"आपके गेम में खिलाड़ी कौन है? ऑब्जेक्ट चुनें (आपकी कार या किरदार) फिर कहें «Multiplayer जोड़ो» — या Player.create से खिलाड़ी जोड़ें।",
"نظام جاهز: اللعب الجماعي":"तैयार सिस्टम: मल्टीप्लेयर",
