"شكل واجهة الغرف":"रूम इंटरफ़ेस का रूप",
"اللاعب (Player)":"खिलाड़ी (Player)",
"بنفس المجسم":"उसी मॉडल के साथ",
"كأشكال بسيطة":"सरल आकारों के रूप में",
"يزامن: {0} — الموقع والدوران وحالة إضافية (NetState) · اللاعبون الآخرون يظهرون {1} ويتحرّكون بسلاسة · الأحداث بين اللاعبين: Events.emit(\"NetEmit\", …).":"सिंक करता है: {0} — पोज़िशन, रोटेशन और अतिरिक्त स्टेट (NetState) · दूसरे खिलाड़ी {1} दिखते हैं और आसानी से चलते हैं · खिलाड़ियों के बीच इवेंट: Events.emit(\"NetEmit\", …)।",
"يعمل عبر غرف NEXUS (Network.room على Firestore) — يحتاج: اتصال الموقع بالسحابة، واللاعب داخلًا (الضيف يكفي). لا يحتاج خادمًا أو مفتاحًا إضافيًا.":"NEXUS रूम (Firestore पर Network.room) से चलता है — ज़रूरी: साइट का क्लाउड से जुड़ा होना, और खिलाड़ी का साइन इन होना (गेस्ट काफ़ी है)। किसी अतिरिक्त सर्वर या की की ज़रूरत नहीं।",
"✓ الآن: السحابة متصلة وأنت داخل — جرّبه: شغّل اللعبة في جهازين (أو نافذتين) واضغط «العب مع الجميع».":"✓ अभी: क्लाउड जुड़ा है और आप साइन इन हैं — आज़माएँ: गेम को दो डिवाइसों (या दो विंडो) में चलाएँ और «सबके साथ खेलें» दबाएँ।",
"لم تسجّل الدخول":"आप साइन इन नहीं हैं",
