"التكلفة: كل لاعب متحرك يكتب حتى 5 مرات في الثانية في Firestore (الخطة المجانية: 20 ألف كتابة يوميًا).":"लागत: हर चलता हुआ खिलाड़ी Firestore में हर सेकंड 5 बार तक लिखता है (फ़्री प्लान: रोज़ 20 हज़ार राइट)।",
