"لصاحب المنصة فقط. الصق هنا «firebaseConfig» من: Firebase Console ← ⚙ Project settings ← General ← Your apps ← Web app ← Config. لا يُحفظ شيء على هذا الجهاز. الناتج ملف index.html جاهز ترفعه إلى Netlify بدل الحالي — فيستخدم كل الزوار نفس المشروع.":"सिर्फ़ प्लेटफ़ॉर्म मालिक के लिए। «firebaseConfig» यहाँ पेस्ट करें: Firebase Console → ⚙ Project settings → General → Your apps → Web app → Config से। इस डिवाइस पर कुछ सेव नहीं होता। नतीजा एक तैयार index.html फ़ाइल है जिसे आप मौजूदा की जगह Netlify पर अपलोड करते हैं — ताकि सभी विज़िटर एक ही प्रोजेक्ट इस्तेमाल करें।",
