"رصيدك، إعلانات بمكافأة، رفع ملفات بروابط مباشرة، طلبات ذكاء إضافية، واشتراك Pro":"आपका बैलेंस, इनाम वाले विज्ञापन, सीधे लिंक के साथ फ़ाइल अपलोड, अतिरिक्त AI अनुरोध, और Pro सदस्यता",
"ضع مفاتيحك مرة واحدة على خادم الموقع: كل الناس يستعملون الذكاء المجاني دون أن يروها":"अपनी कीज़ एक बार साइट के सर्वर पर डालें: सब लोग उन्हें देखे बिना मुफ़्त AI इस्तेमाल करते हैं",
"يحذف النسخ المؤقتة على هذا الجهاز فقط (المجسمات في الذاكرة، أيقونات الأصول، نسخ العمل دون إنترنت). الأصول نفسها — سجلّاتها في Firebase وملفاتها في Drive — لا تُمس، وتُعاد أيقوناتها منها":"सिर्फ़ इस डिवाइस की अस्थायी कॉपियाँ हटाता है (मेमोरी में मॉडल, एसेट आइकन, ऑफ़लाइन काम की कॉपियाँ)। एसेट ख़ुद — Firebase में उनके रिकॉर्ड और Drive में उनकी फ़ाइलें — नहीं छुए जाते, और उनके आइकन उन्हीं से वापस आते हैं",
"الأصول ≠ الكود":"एसेट ≠ कोड",
"• الأصول (GLB/صور/صوت) بيانات فقط ولا تُنفَّذ أبدًا؛ لا يُقبل رفع ملفات سكربت كأصول. • كود مطوّر آخر لا يعمل إلا بموافقتك الصريحة، ويمكنك قراءته قبل التشغيل. • كود الآخرين (ألعابهم المنشورة وكل مشروع فيه فريق) يعمل في صندوق معزول (iframe sandbox) بمصدر مجهول: لا يصل إلى جلسة دخولك ولا تخزين الموقع ولا مفاتيح AI ولا Firebase — فقط عبر جسر يسمح بغرف اللعبة وحفظها وأصولها المقروءة. • كودك أنت في مشروعك الفردي يعمل داخل الصفحة كما كان (التقييد هناك حاجز سلامة).":"• एसेट (GLB/इमेज/आवाज़) सिर्फ़ डेटा हैं और कभी नहीं चलते; स्क्रिप्ट फ़ाइलें एसेट के रूप में स्वीकार नहीं होतीं। • किसी दूसरे डेवलपर का कोड सिर्फ़ आपकी साफ़ सहमति से चलता है, और चलाने से पहले आप इसे पढ़ सकते हैं। • दूसरों का कोड (उनके प्रकाशित गेम्स और टीम वाला हर प्रोजेक्ट) एक अलग बॉक्स (iframe sandbox) में अज्ञात स्रोत के साथ चलता है: यह आपके साइन-इन सेशन, साइट स्टोरेज, AI कीज़ या Firebase तक नहीं पहुँचता — सिर्फ़ एक पुल के ज़रिए जो गेम रूम, सेव और पढ़ने लायक एसेट की अनुमति देता है। • आपके अकेले प्रोजेक्ट में आपका अपना कोड पहले की तरह पेज के अंदर चलता है (वहाँ पाबंदी एक सुरक्षा दीवार है)।",
"قواعد واحدة للمنصة كلها. العدادات والملكية والخصوصية تُفرض على الخادم لا في المتصفح.":"पूरे प्लेटफ़ॉर्म के लिए एक ही नियम। काउंटर, मालिकाना हक़ और प्राइवेसी सर्वर पर लागू होते हैं, ब्राउज़र में नहीं।",
